package main

import (
	"bufio"
	"bytes"
	"math"
	"strconv"
	"strings"
	"sync/atomic"
)

// The world map on the Analytics page: country shapes from web/world.txt
// (generated by tools/worldmap), filled from the same sequential ramp as
// the heatmap. Drawn inline as SVG, so it follows the theme like every
// other chart and needs no request of its own.

// geoCredit is set once a DB-IP database is loaded, so the map carries the
// attribution its CC BY licence asks for.
var geoCredit atomic.Bool

type worldShape struct {
	Code string // ISO 3166-1 alpha-2, or "" for land with no code
	D    string // SVG path data
}

var world = func() (w struct {
	ViewBox string
	Shapes  []worldShape
}) {
	b, err := webFS.ReadFile("web/world.txt")
	if err != nil {
		panic(err)
	}
	sc := bufio.NewScanner(bytes.NewReader(b))
	sc.Buffer(nil, 1<<20)
	for sc.Scan() {
		line := sc.Text()
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		k, v, _ := strings.Cut(line, " ")
		switch {
		case k == "viewBox":
			w.ViewBox = v
		case k == "-":
			w.Shapes = append(w.Shapes, worldShape{D: v})
		default:
			w.Shapes = append(w.Shapes, worldShape{Code: k, D: v})
		}
	}
	return w
}()

type mapShape struct {
	Code  string
	D     string
	Level int // 0 = no clicks, 1-5 = the heat ramp
	Name  string
	N     int
	Pct   string
}

type mapView struct {
	ViewBox  string
	Shapes   []mapShape
	Max      int
	Unknown  int // clicks with no country
	Unmapped int // clicks from places too small or not on the map
	Total    int
}

// geoLevel puts n on a log scale of five steps, so one busy country does
// not wash every other one out to the lightest shade.
func geoLevel(n, maxN int) int {
	switch {
	case n <= 0:
		return 0
	case maxN <= 1 || n >= maxN:
		return 5
	}
	return min(5, 1+int(math.Log(float64(n))/math.Log(float64(maxN))*4.999))
}

func makeWorldMap(st *Stats) mapView {
	v := mapView{ViewBox: world.ViewBox, Total: st.Clicks}
	counts := map[string]int{}
	for _, r := range st.GeoCountries {
		code := strings.ToUpper(r.Key)
		if code == "" || code == "XX" || code == "T1" {
			v.Unknown += r.N
			continue
		}
		counts[code] = r.N
		v.Max = max(v.Max, r.N)
	}
	onMap := map[string]bool{}
	for _, s := range world.Shapes {
		ms := mapShape{Code: s.Code, D: s.D}
		if s.Code != "" {
			onMap[s.Code] = true
			ms.N = counts[s.Code]
			ms.Level = geoLevel(ms.N, v.Max)
			ms.Name = countryName(s.Code)
			if st.Clicks > 0 {
				ms.Pct = strconv.Itoa(int(math.Round(float64(ms.N)/float64(st.Clicks)*100))) + "%"
			}
		}
		v.Shapes = append(v.Shapes, ms)
	}
	for code, n := range counts {
		if !onMap[code] {
			v.Unmapped += n
		}
	}
	return v
}
